(()=>{const root=document.body,button=document.querySelector('.theme-toggle');if(!button)return;const choice=()=>{try{return localStorage.getItem('archorizon-theme')}catch{return null}};const set=(value)=>{root.dataset.theme=value;button.textContent=value==='dark'?'☀ Light mode':'☾ Dark mode';button.setAttribute('aria-pressed',String(value==='dark'))};set(choice()|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));button.addEventListener('click',()=>{const next=root.dataset.theme==='dark'?'light':'dark';set(next);try{localStorage.setItem('archorizon-theme',next)}catch{}})})();